const options=['Quiet strip','Two-line timer','Small tile','Inline controls','Session card'];let selected=0,paused=false,seconds=1492;const svg=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${name==='pause'?'<path d="M8 5v14M16 5v14"/>':name==='play'?'<path d="m8 5 11 7-11 7Z"/>':name==='open'?'<path d="M14 4h6v6M20 4l-9 9M10 4H4v16h16v-6"/>':'<path d="m6 6 12 12M18 6 6 18"/>'}</svg>`;const controls=()=>`<div class="controls"><button id="pause" aria-label="${paused?'Resume':'Pause'}">${svg(paused?'play':'pause')}</button><button id="open" aria-label="Open Focus">${svg('open')}</button><button id="hide" aria-label="Hide timer">${svg('close')}</button></div>`;const time=()=>`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;function render(){const w=document.querySelector('#widget');w.className='abcde'[selected];const title='<span class="title">Check pipeline data quality</span>',t=`<span class="time">${time()}</span>`;w.innerHTML=selected===0?`<div class="drag">${t}${controls()}</div><div class="progress"><i></i></div>`:selected===3?`<div class="drag">${title}${t}${controls()}</div>`:`<div class="drag">${title}<button id="hide" aria-label="Hide timer">${svg('close')}</button></div><div class="bottom">${t}${controls().replace(/<button id="hide".*?<\/button>/,'')}</div>${selected===1?'<div class="progress"><i></i></div>':''}`;document.querySelector('nav').innerHTML=options.map((x,i)=>`<button data-option="${i}" aria-pressed="${selected===i}">${'ABCDE'[i]} · ${x}</button>`).join('');document.querySelector('#selection').textContent=`${'ABCDE'[selected]} · ${options[selected]}`;document.querySelector('#choose').textContent=`Choose ${'ABCDE'[selected]}`;document.querySelector('#pause').onclick=()=>{paused=!paused;render()};document.querySelector('#hide').onclick=()=>{w.classList.add('closed');document.querySelector('#selection').textContent='Hidden · select an option to reopen'};document.querySelector('#open').onclick=()=>{document.querySelector('#selection').textContent='Focus opened · preview only'};w.querySelector('.drag').onpointerdown=e=>{if(e.target.closest('button'))return;const r=w.getBoundingClientRect(),m=w.parentElement.getBoundingClientRect(),dx=e.clientX-r.left,dy=e.clientY-r.top;w.setPointerCapture(e.pointerId);w.onpointermove=e=>{w.style.left=Math.max(0,Math.min(m.width-r.width,e.clientX-m.left-dx))+'px';w.style.top=Math.max(0,Math.min(m.height-r.height,e.clientY-m.top-dy))+'px';w.style.right='auto';w.style.bottom='auto'};w.onpointerup=()=>{w.onpointermove=null}};}document.querySelector('nav').onclick=e=>{const b=e.target.closest('[data-option]');if(b){selected=+b.dataset.option;render()}};document.querySelector('#theme').onclick=()=>{document.body.classList.toggle('dark');document.querySelector('#theme').textContent=document.body.classList.contains('dark')?'Light':'Dark'};document.querySelector('#choose').onclick=()=>{localStorage.setItem('tempo-widget-choice','ABCDE'[selected]);document.querySelector('#selection').textContent=`${'ABCDE'[selected]} chosen · reply in chat to approve`};setInterval(()=>{if(!paused&&seconds>0){seconds--;document.querySelector('.time').textContent=time()}},1000);render();
